cssCode:
.progress-container {
  position: sticky; top: 0; left: 0; 
  width: 100%; height: 6px;
  background: rgba(255, 255, 255, 0.1); 
  z-index: 9999;
}
.progress-bar {
  height: 100%; width: 0%;
  background: linear-gradient(90deg, #00ffcc, #ff00ff);
  box-shadow: 0 0 15px #00ffcc;
  border-radius: 0 5px 5px 0;
}
.dummy-content { 
  height: 300vh; padding-top: 50px; text-align: center; 
  color: #555; font-family: sans-serif; 
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:transparent;position:relative;';

const pContainer = document.createElement('div');
pContainer.className = 'progress-container';
const pBar = document.createElement('div');
pBar.className = 'progress-bar';
pContainer.appendChild(pBar);

const content = document.createElement('div');
content.className = 'dummy-content';
content.innerText = 'SCROLL DOWN TO FILL NEON BAR ↓';

c.appendChild(pContainer);
c.appendChild(content);

c.addEventListener('scroll', () => {
  const maxScroll = c.scrollHeight - c.clientHeight;
  const scrolled = (c.scrollTop / maxScroll) * 100;
  pBar.style.width = scrolled + '%';
});
